# Generated by build.py from recipe.yml for recipe imap-poll-until-the-mail-arrives. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'reset.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Reset your password`n`nFollow the link to choose a new password.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'slow-app.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for an app that mails a user some seconds after a request: it returns at once`n# and sends the message in the background after the delay.`n# Usage: sh slow-app.sh <smtp port> <seconds> <recipient> <message file>`n(`n  sleep `"`$2`"`n  curl -s --crlf -u app@example.com:apppass --mail-from app@example.com \`n    --mail-rcpt `"`$3`" -T `"`$4`" `"smtp://127.0.0.1:`$1/example.com`"`n) > /dev/null 2>&1 &`n")
[IO.File]::WriteAllText((Join-Path $PWD 'wait-for-mail.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Runs an IMAP SEARCH once a second until it finds a message or the tries run out.`n# Usage: sh wait-for-mail.sh <user:password> <search URL> <tries>`ntries=`$3`nwhile [ `"`$tries`" -gt 0 ]; do`n  found=`$(curl -sS -u `"`$1`" `"`$2`") || exit `$?`n  found=`$(printf '%s' `"`$found`" | tr -d '\r')`n  case `$found in`n    `"* SEARCH `"[0-9]*)`n      echo `"found: UID `${found#\* SEARCH }`"`n      exit 0 ;;`n  esac`n  tries=`$((tries - 1))`n  if [ `"`$tries`" -gt 0 ]; then`n    sleep 1`n  fi`ndone`necho `"no matching mail after `$3 tries`"`nexit 1`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'carol@example.com:carolpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh slow-app.sh 8080 3 ann@example.com reset.eml && sh wait-for-mail.sh ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Reset%20your%20password%22" 10 } finally { Stop-Process $server0 }
